content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: #f0f2f5;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

.calculator-container {
  background-color: #ffffff;
  border-radius: 16px;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.1);
  width: 340px;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.calculator-display {
  background-color: #22252a;
  color: #ffffff;
  font-size: 2.2rem;
  padding: 20px;
  border-radius: 12px;
  text-align: right;
  min-height: 80px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  word-break: break-all;
  overflow: hidden;
}

.calculator-keypad {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.calc-btn {
  background-color: #f0f2f5;
  border: none;
  border-radius: 10px;
  font-size: 1.25rem;
  font-weight: 600;
  color: #333333;
  padding: 16px 0;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
  user-select: none;
}

.calc-btn:hover {
  background-color: #e4e6eb;
}

.calc-btn:active {
  transform: scale(0.95);
}

.calc-btn-operator {
  background-color: #ff9f0a;
  color: #ffffff;
}

.calc-btn-operator:hover {
  background-color: #f59300;
}

.calc-btn-clear {
  background-color: #ff3b30;
  color: #ffffff;
}

.calc-btn-clear:hover {
  background-color: #e0322b;
}

.calc-btn-equals {
  background-color: #34c759;
  color: #ffffff;
}

.calc-btn-equals:hover {
  background-color: #2eb04f;
}

.calc-btn-zero {
  grid-column: span 2;
}

import { useState } from 'react'
import './index.css'

export default function App() {
  const [display, setDisplay] = useState('0')
  const [firstOperand, setFirstOperand] = useState<number | null>(null)
  const [operator, setOperator] = useState<string | null>(null)
  const [waitingForSecondOperand, setWaitingForSecondOperand] = useState(false)

  const inputDigit = (digit: string) => {
    if (waitingForSecondOperand) {
      setDisplay(digit)
      setWaitingForSecondOperand(false)
    } else {
      setDisplay(display === '0' ? digit : display + digit)
    }
  }

  const inputDecimal = (dot: string) => {
    if (waitingForSecondOperand) {
      setDisplay('0' + dot)
      setWaitingForSecondOperand(false)
      return
    }

    if (!display.includes(dot)) {
      setDisplay(display + dot)
    }
  }

  const clearCalculator = () => {
    setDisplay('0')
    setFirstOperand(null)
    setOperator(null)
    setWaitingForSecondOperand(false)
  }

  const performOperation = (nextOperator: string) => {
    const inputValue = parseFloat(display)

    if (firstOperand === null) {
      setFirstOperand(inputValue)
    } else if (operator) {
      const result = calculate(firstOperand, inputValue, operator)
      setDisplay(String(result))
      setFirstOperand(result)
    }

    setWaitingForSecondOperand(true)
    setOperator(nextOperator)
  }

  const calculate = (first: number, second: number, op: string): number => {
    switch (op) {
      case '+':
        return first + second
      case '-':
        return first - second
      case '×':
        return first * second
      case '÷':
        return second === 0 ? 0 : first / second
      default:
        return second
    }
  }

  const handleEquals = () => {
    if (!operator || firstOperand === null) return

    const inputValue = parseFloat(display)
    const result = calculate(firstOperand, inputValue, operator)
    setDisplay(String(result))
    setFirstOperand(null)
    setOperator(null)
    setWaitingForSecondOperand(false)
  }

  return (
    <div className="calculator-container">
      <div className="calculator-display">{display}</div>
      <div className="calculator-keypad">
        <button className="calc-btn calc-btn-clear" onClick={clearCalculator}>AC</button>
        <button className="calc-btn calc-btn-operator" onClick={() => performOperation('÷')}>÷</button>
        <button className="calc-btn calc-btn-operator" onClick={() => performOperation('×')}>×</button>
        <button className="calc-btn calc-btn-operator" onClick={() => performOperation('-')}>-</button>

        <button className="calc-btn" onClick={() => inputDigit('7')}>7</button>
        <button className="calc-btn" onClick={() => inputDigit('8')}>8</button>
        <button className="calc-btn" onClick={() => inputDigit('9')}>9</button>
        <button className="calc-btn calc-btn-operator" onClick={() => performOperation('+')}>+</button>

        <button className="calc-btn" onClick={() => inputDigit('4')}>4</button>
        <button className="calc-btn" onClick={() => inputDigit('5')}>5</button>
        <button className="calc-btn" onClick={() => inputDigit('6')}>6</button>
        <button className="calc-btn calc-btn-equals" onClick={handleEquals} style={{ gridRow: 'span 2', padding: '0' }}>=</button>

        <button className="calc-btn" onClick={() => inputDigit('1')}>1</button>
        <button className="calc-btn" onClick={() => inputDigit('2')}>2</button>
        <button className="calc-btn" onClick={() => inputDigit('3')}>3</button>

        <button className="calc-btn calc-btn-zero" onClick={() => inputDigit('0')}>0</button>
        <button className="calc-btn" onClick={() => inputDecimal('.')}>.</button>
      </div>
    </div>
  )
}
